  shader(sh);

  sh.setUniform("u_resolution", [width, height]);
  sh.setUniform("u_time", millis() / 1000.0);
  sh.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0)]);

//   // something for the shader to draw on
  rect(0,0,width, height);
}

function windowResized(){ resizeCanvas(width, height); }

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
    lapse = millis();
  } 
}



// === Tab: shockwave ===
// https://www.shadertoy.com/view/lssBRM
// ShockWave technique

var swVert = `
	attribute vec3 aPosition;

	void main() {
		vec4 pos = vec4(aPosition, 1.0);
		pos.xy = pos.xy * 2.0 - 1.0;

		gl_Position = pos;
	}
`;

var swFrag = `
	#ifdef GL_ES
			precision mediump float;
	#endif

	uniform vec2 u_resolution;
	uniform vec2 u_mouse;
	uniform float u_time;


	float random (in vec2 _st) {
		return fract(sin(dot(_st.xy,vec2(12.9898,78.233)))*43758.5453123);
	}

	float noise (in vec2 _st) {
		vec2 i = floor(_st);
		vec2 f = fract(_st);

		// Four corners in 2D of a tile
		float a = random(i);
		float b = random(i + vec2(1.0, 0.0));
		float c = random(i + vec2(0.0, 1.0));
		float d = random(i + vec2(1.0, 1.0));

		vec2 u = f * f * (3.0 - 2.0 * f);

		return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
	}

	#define NUM_OCTAVES 7

	float fbm ( in vec2 _st) {
		float v = 0.0;
		float a = 0.5;
		vec2 shift = vec2(10.0);

		// Rotate to reduce axial bias
		mat2 rot = mat2( cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
		for (int i = 0; i < NUM_OCTAVES; ++i) {
			v += a * noise(_st);
			_st = rot * _st * 2.0 + shift;
			a *= 0.6;
		}
		return v;
	}


// -----------------------------------------------------------------------------

	vec2 rectToPolar(vec2 p, vec2 ms) {
		p -= ms / 1.35;
		const float PI = 3.1415926534;
		float r = length(p);
		float a = ((atan(p.y+0.2, p.x) / PI) * 0.85 + 0.5) * ms.x;
		return vec2(a, r);	
	}

	float effect(vec2 p, float o) {
		p *= 1.5;
		float f1 = fbm(p * vec2(13.0, 1.0) + 100.0 + vec2(0.0, o) );
		float e = fbm(p * vec2(15.0, 1.0) + vec2(f1 * 0.85, o));
    e = abs(e) * sqrt(p.y / 5.0);
    return e * 0.75;
	}

	float line(float v, float from, float to, float f)
	{
		float d = max(from - v, v - to);
		return 1.0 - smoothstep(0.0, f, d);
	}

// -----------------------------------------------------------------------------

	float sw(vec2 p, vec2 ms) {

		p = rectToPolar(p, ms);
		p.x = mod(p.x + 2.95, ms.x);

		// Create the seem mask at that offset
		const float b = 0.5;
		const float d = 0.04;
		float seem = line(p.x, -1.0, d, b) + line(p.x, ms.x - d, ms.x + 1.0, b);
		seem = min(seem, 1.0);

		float s1 = effect(p, 0.0);

		// Create another noise to fade to, but the seem has the be at a different position
		p.x = mod(p.x + 3.6, ms.x);
		float s2 = effect(p, -1020.0);

		// Blend them together
		float s = s1;
		s = mix(s1, s2, seem);

    float perc = min( max(abs(sin(u_time * 0.1)), u_time * 0.1), 1.0);

    float f1 = perc * 0.25;
    float f2 = perc * 1.;

    float m = line(p.y, 0.1, f1 + s * f2 * sin(1.5), 0.2);

		return smoothstep(0.31, 0.6, m);
	}

	void main() {
		vec2 st = gl_FragCoord.xy / u_resolution.xy * 5.;
		vec3 color = vec3(0.0);

		vec2 q = vec2(0.);
		q.x = fbm(st + 0.00 * u_time);
		q.y = fbm(st + vec2(0.5));

		vec2 r = vec2(0.);
		r.x = fbm(st + 1.0 * q + vec2(1.7,9.2) + 0.150 * u_time);
		r.y = fbm(st + 1.0 * q + vec2(28.3,2.8) + 0.526 * u_time );

		float f = fbm(st + r + fbm(q * fbm(r)));

		color = mix(
		vec3(0.901961,0.619608,0.166667),
		vec3(0.666667,0.666667,0.198039),
		clamp((f*f)*4.0,0.0,1.0));

		color = mix(color, vec3(.9,.6,0.364706), clamp(length(q),0.25,1.0));
		color = mix(color, vec3(0.96667,0.8,0.91), clamp(length(r.x),0.0,1.0));
		color = mix(color, vec3(0.366667,0.3,0.3), clamp(length(r.y),0.0,1.0));


		vec2 p = gl_FragCoord.xy / u_resolution.xy;
    float m = u_resolution.x / u_resolution.y;
		vec2 ms = vec2(m, 1.5);

    float c = .90;

    float s = sw(p, ms);
    c /= s;
    c += s;
    float t = random(p * 2.0);

		vec3 pic = vec3(f);

   	vec3 col = mix(color, pic, c); 

    // Some grain
    col -= (2.0 - s) * t * 0.04;

		gl_FragColor = vec4((f*f*f + .26 * f*f + .15 * f) * col,1.0);
	}
`

